/**
 * The intermediate format an agent writes to draw a Happy UI block in a chat
 * message: a small, closed tree of components that Happy renders with its own
 * catalog. The model never writes markup or code; it writes this tree inside a
 * ` ```happy-ui ` fence, and the fence is drawn once it has closed.
 *
 * The first use is a guided review: a tour of a change in the conversation,
 * with an overview, before/after, and chapters that gather files by idea. The
 * same six nodes explain something that is not a change at all.
 *
 * Every string here is plain text, not Markdown. The block is sized before it
 * mounts, like the rest of the transcript, and plain words keep that model
 * exact; a reference to code is a file node or a diff node, never prose.
 */

export const HAPPY_UI_FENCE_LABEL = "happy-ui";
export const HAPPY_UI_VERSION = 1;

/** Lines counted from 1, both ends included, the way every editor counts. */
export interface HappyUiLineRange {
    readonly startLine: number;
    readonly endLine: number;
}

/** One file a chapter gathers, optionally the lines that chapter is about. */
export interface HappyUiFile {
    readonly path: string;
    readonly lines?: HappyUiLineRange;
    /** A few plain words on what this file contributes to the chapter. */
    readonly note?: string;
}

/** A node a chapter may hold below its files. */
export type HappyUiChapterChild = HappyUiDiffNode | HappyUiMermaidNode;

/** One sentence of context, so the reader knows what they are looking at. */
export interface HappyUiContextNode {
    readonly type: "context";
    readonly text: string;
}

/** The steps the change takes, or the steps an explanation walks through. */
export interface HappyUiStepsNode {
    readonly type: "steps";
    readonly items: readonly string[];
}

/** How something behaved before and how it behaves now. */
export interface HappyUiBeforeAfterNode {
    readonly type: "beforeAfter";
    readonly before: string;
    readonly after: string;
}

/** One idea in ordinary words, and the files that carry it. Not a folder. */
export interface HappyUiChapterNode {
    readonly type: "chapter";
    readonly title: string;
    readonly text?: string;
    readonly files: readonly HappyUiFile[];
    readonly children?: readonly HappyUiChapterChild[];
}

/**
 * A run of lines in a real file's change. The agent names the place; the lines
 * themselves come from the actual diff, so this node can never show code that
 * is not in the change.
 */
export interface HappyUiDiffNode {
    readonly type: "diff";
    readonly path: string;
    readonly lines: HappyUiLineRange;
}

/** A diagram, drawn by the Mermaid component the transcript already has. */
export interface HappyUiMermaidNode {
    readonly type: "mermaid";
    readonly source: string;
}

export type HappyUiNode =
    | HappyUiContextNode
    | HappyUiStepsNode
    | HappyUiBeforeAfterNode
    | HappyUiChapterNode
    | HappyUiDiffNode
    | HappyUiMermaidNode;

/**
 * What the tree is for. A `tour` is held to the shape of a guided review:
 * context first, steps, at least one before/after, and chapters that each
 * name at least one file. An `explanation` may use any of the nodes in any
 * order.
 */
export type HappyUiKind = "tour" | "explanation";

export interface HappyUiDocument {
    readonly version: typeof HAPPY_UI_VERSION;
    readonly kind: HappyUiKind;
    readonly children: readonly HappyUiNode[];
}

export type HappyUiParsed =
    | { readonly type: "ready"; readonly document: HappyUiDocument }
    | { readonly type: "invalid"; readonly reason: string };

const MAX_SOURCE_BYTES = 262_144;
const MAX_NODES = 200;
const MAX_TEXT = 4_000;
const MAX_ITEMS = 50;
const MAX_FILES = 100;
const MAX_LINE = 10_000_000;

class Invalid extends Error {}

function fail(reason: string): never {
    throw new Invalid(reason);
}

function record(value: unknown, where: string): Record<string, unknown> {
    if (typeof value !== "object" || value === null || Array.isArray(value))
        fail(`${where} must be an object.`);
    return value as Record<string, unknown>;
}

function text(value: unknown, where: string, allowEmpty = false): string {
    if (typeof value !== "string") fail(`${where} must be text.`);
    const trimmed = value.trim();
    if (!allowEmpty && trimmed.length === 0) fail(`${where} must not be empty.`);
    if (trimmed.length > MAX_TEXT) fail(`${where} is too long.`);
    return trimmed;
}

function optionalText(value: unknown, where: string): string | undefined {
    if (value === undefined) return undefined;
    const trimmed = text(value, where, true);
    return trimmed.length === 0 ? undefined : trimmed;
}

function list(value: unknown, where: string, max: number): readonly unknown[] {
    if (!Array.isArray(value)) fail(`${where} must be a list.`);
    if (value.length > max) fail(`${where} has too many entries.`);
    return value;
}

function lineRange(value: unknown, where: string): HappyUiLineRange {
    const range = record(value, where);
    const startLine = range["startLine"];
    const endLine = range["endLine"];
    if (
        typeof startLine !== "number" ||
        typeof endLine !== "number" ||
        !Number.isInteger(startLine) ||
        !Number.isInteger(endLine)
    )
        fail(`${where} must give whole startLine and endLine numbers.`);
    if (startLine < 1 || endLine < startLine || endLine > MAX_LINE)
        fail(`${where} is not a line range counted from 1.`);
    return { startLine, endLine };
}

function path(value: unknown, where: string): string {
    const value_ = text(value, where);
    if (value_.startsWith("/") || value_.includes("\\") || value_.split("/").includes(".."))
        fail(`${where} must be a path inside the workspace.`);
    return value_;
}

function file(value: unknown, where: string): HappyUiFile {
    const file_ = record(value, where);
    const note = optionalText(file_["note"], `${where}.note`);
    const lines =
        file_["lines"] === undefined ? undefined : lineRange(file_["lines"], `${where}.lines`);
    return {
        path: path(file_["path"], `${where}.path`),
        ...(lines === undefined ? {} : { lines }),
        ...(note === undefined ? {} : { note }),
    };
}

function chapterChild(
    value: unknown,
    where: string,
    count: { nodes: number },
): HappyUiChapterChild {
    const child = node(value, where, count);
    if (child.type !== "diff" && child.type !== "mermaid")
        fail(`${where} must be a diff or a mermaid node; a chapter holds nothing else.`);
    return child;
}

function node(value: unknown, where: string, count: { nodes: number }): HappyUiNode {
    count.nodes += 1;
    if (count.nodes > MAX_NODES) fail("The block has too many nodes.");
    const node_ = record(value, where);
    const type = node_["type"];
    switch (type) {
        case "context":
            return { type, text: text(node_["text"], `${where}.text`) };
        case "steps": {
            const items = list(node_["items"], `${where}.items`, MAX_ITEMS).map((item, index) =>
                text(item, `${where}.items[${String(index)}]`),
            );
            if (items.length === 0) fail(`${where}.items must name at least one step.`);
            return { type, items };
        }
        case "beforeAfter":
            return {
                type,
                before: text(node_["before"], `${where}.before`),
                after: text(node_["after"], `${where}.after`),
            };
        case "chapter": {
            const files = list(node_["files"], `${where}.files`, MAX_FILES).map((entry, index) =>
                file(entry, `${where}.files[${String(index)}]`),
            );
            const children =
                node_["children"] === undefined
                    ? undefined
                    : list(node_["children"], `${where}.children`, MAX_ITEMS).map((entry, index) =>
                          chapterChild(entry, `${where}.children[${String(index)}]`, count),
                      );
            const text_ = optionalText(node_["text"], `${where}.text`);
            return {
                type,
                title: text(node_["title"], `${where}.title`),
                ...(text_ === undefined ? {} : { text: text_ }),
                files,
                ...(children === undefined || children.length === 0 ? {} : { children }),
            };
        }
        case "diff":
            return {
                type,
                path: path(node_["path"], `${where}.path`),
                lines: lineRange(node_["lines"], `${where}.lines`),
            };
        case "mermaid":
            return { type, source: text(node_["source"], `${where}.source`) };
        default:
            fail(
                typeof type === "string"
                    ? `${where} has an unknown type "${type}".`
                    : `${where} has no type.`,
            );
    }
}

/** The shape a guided review must take, checked after the tree is well formed. */
function tourAssert(children: readonly HappyUiNode[]): void {
    if (children[0]?.type !== "context") fail("A tour starts with one sentence of context.");
    if (!children.some((child) => child.type === "steps")) fail("A tour lists its steps.");
    if (!children.some((child) => child.type === "beforeAfter"))
        fail("A tour shows at least one before/after.");
    const chapters = children.filter((child) => child.type === "chapter");
    if (chapters.length === 0) fail("A tour has at least one chapter.");
    for (const chapter of chapters)
        if (chapter.files.length === 0) fail(`Chapter "${chapter.title}" names no files.`);
}

/**
 * Reads one fenced block into a document, or says why it cannot be drawn.
 * Nothing here is ever rendered as markup: a failure keeps the source on screen
 * with the reason beside it.
 */
export function happyUiParse(source: string): HappyUiParsed {
    try {
        if (new TextEncoder().encode(source).byteLength > MAX_SOURCE_BYTES)
            fail("The block is too large to draw.");
        let json: unknown;
        try {
            json = JSON.parse(source);
        } catch {
            fail("The block is not valid JSON.");
        }
        const root = record(json, "The block");
        if (root["version"] !== HAPPY_UI_VERSION)
            fail(`The block must declare "version": ${String(HAPPY_UI_VERSION)}.`);
        const kind = root["kind"];
        if (kind !== "tour" && kind !== "explanation")
            fail('The block must declare "kind": "tour" or "explanation".');
        const count = { nodes: 0 };
        const children = list(root["children"], "children", MAX_NODES).map((entry, index) =>
            node(entry, `children[${String(index)}]`, count),
        );
        if (children.length === 0) fail("The block has no nodes.");
        if (kind === "tour") tourAssert(children);
        return { type: "ready", document: { version: HAPPY_UI_VERSION, kind, children } };
    } catch (error) {
        if (error instanceof Invalid) return { type: "invalid", reason: error.message };
        return { type: "invalid", reason: "The block could not be read." };
    }
}

/** Every diff node and file reference in a document, in reading order. */
export function happyUiReferences(
    document: HappyUiDocument,
): readonly { readonly path: string; readonly lines?: HappyUiLineRange }[] {
    const out: { readonly path: string; readonly lines?: HappyUiLineRange }[] = [];
    for (const child of document.children) {
        if (child.type === "diff") out.push({ path: child.path, lines: child.lines });
        if (child.type !== "chapter") continue;
        for (const file of child.files) out.push(file);
        for (const grandchild of child.children ?? [])
            if (grandchild.type === "diff")
                out.push({ path: grandchild.path, lines: grandchild.lines });
    }
    return out;
}

