import { parseDiffFromFile } from "@pierre/diffs";
import type { DiffLine } from "./DiffSnippet";
import {
    HAPPY_UI_FENCE_LABEL,
    happyUiParse,
    happyUiReferences,
    type HappyUiLineRange,
} from "./happyUi";

/**
 * What one diff node shows, read from the real change.
 *
 * - `ready` — the lines of the change inside the named range. `added` and
 *   `removed` count the changed ones; both zero means the agent pointed at
 *   lines that did not change, which the block says out loud.
 * - `loading` — the file's change is still being read.
 * - `missing` — the file is not part of this change at all.
 * - `error` — the change could not be read.
 */
export type HappyUiDiffView =
    | {
          readonly type: "ready";
          readonly lines: readonly DiffLine[];
          readonly added: number;
          readonly removed: number;
      }
    | { readonly type: "loading" }
    | { readonly type: "missing" }
    | { readonly type: "error"; readonly message: string };

/** Whether a file a chapter names is part of the change being toured. */
export type HappyUiFileView = "changed" | "unchanged" | "unknown";

/**
 * The real change behind a Happy UI block, supplied by the surface that owns
 * the workspace. Both reads are asked while rendering and while sizing rows,
 * so each must be a pure read of the owner's current snapshot; recording that
 * something is wanted is fine, publishing in the same call is not.
 *
 * Without a grounding every diff node reads as `unknown` and every file as
 * `unknown`: a transcript with no checkout behind it has no change to show.
 */
export interface HappyUiGrounding {
    diff(path: string, lines: HappyUiLineRange): HappyUiDiffView;
    file(path: string): HappyUiFileView;
}

/** The most lines one diff node shows; a tour points, it does not reprint. */
export const HAPPY_UI_DIFF_MAX_LINES = 80;

/** The two sides of one changed file, as the workspace holds them. */
export interface HappyUiChangedFile {
    readonly path: string;
    readonly oldContent: string;
    readonly newContent: string;
}

type Ordered = { readonly anchor: number; readonly order: number; readonly line: DiffLine };

/**
 * The lines of a change inside a range of the file as it now stands:
 * additions and unchanged lines by their current number, deletions by their
 * old number, placed where they were taken out. A deleted file is read by its
 * old numbers, since it has no current ones.
 */
export function happyUiDiffLines(
    file: HappyUiChangedFile,
    range: HappyUiLineRange,
): Extract<HappyUiDiffView, { type: "ready" }> {
    const meta = parseDiffFromFile(
        { name: file.path, contents: file.oldContent },
        { name: file.path, contents: file.newContent },
    );
    const deleted = file.newContent.length === 0 && file.oldContent.length > 0;
    const entries: Ordered[] = [];
    const covered = new Set<number>();
    for (const hunk of meta.hunks) {
        for (const segment of hunk.hunkContent) {
            if (segment.type === "context") {
                for (let index = 0; index < segment.lines; index += 1) {
                    const number = segment.additionLineIndex + index + 1;
                    covered.add(number);
                    entries.push({
                        anchor: number,
                        order: 1,
                        line: {
                            kind: "context",
                            number,
                            text: meta.additionLines[segment.additionLineIndex + index] ?? "",
                        },
                    });
                }
                continue;
            }
            const insertion = segment.additionLineIndex + 1;
            for (let index = 0; index < segment.deletions; index += 1) {
                const number = segment.deletionLineIndex + index + 1;
                entries.push({
                    anchor: deleted ? number : insertion,
                    order: 0,
                    line: {
                        kind: "del",
                        number,
                        text: meta.deletionLines[segment.deletionLineIndex + index] ?? "",
                    },
                });
            }
            for (let index = 0; index < segment.additions; index += 1) {
                const number = segment.additionLineIndex + index + 1;
                covered.add(number);
                entries.push({
                    anchor: number,
                    order: 1,
                    line: {
                        kind: "add",
                        number,
                        text: meta.additionLines[segment.additionLineIndex + index] ?? "",
                    },
                });
            }
        }
    }
    if (!deleted)
        for (let number = range.startLine; number <= range.endLine; number += 1) {
            if (covered.has(number) || number > meta.additionLines.length) continue;
            entries.push({
                anchor: number,
                order: 1,
                line: { kind: "context", number, text: meta.additionLines[number - 1] ?? "" },
            });
        }
    const lines = entries
        .filter(
            (entry) =>
                entry.anchor >= range.startLine &&
                entry.anchor <= (entry.order === 0 && !deleted ? range.endLine + 1 : range.endLine),
        )
        .sort((left, right) => left.anchor - right.anchor || left.order - right.order)
        .slice(0, HAPPY_UI_DIFF_MAX_LINES)
        // The parser keeps each line's newline; the snippet draws one row per line.
        .map((entry) => ({ ...entry.line, text: entry.line.text.replace(/\r?\n$/u, "") }));
    let added = 0;
    let removed = 0;
    for (const line of lines) {
        if (line.kind === "add") added += 1;
        if (line.kind === "del") removed += 1;
    }
    return { type: "ready", lines, added, removed };
}

/**
 * The lines a diff node paints for what the grounding answered, never fewer
 * than one: a change still loading, a file outside the change, a read that
 * failed, or a range with nothing changed in it each say so on a line of their
 * own. The block and the row model both draw from this, so they agree.
 */
export function happyUiDiffDisplayLines(view: HappyUiDiffView | undefined): readonly DiffLine[] {
    if (view === undefined) return [{ kind: "meta", text: "No change to show here." }];
    switch (view.type) {
        case "loading":
            return [{ kind: "meta", text: "Reading the change…" }];
        case "missing":
            return [{ kind: "meta", text: "Not part of this change." }];
        case "error":
            return [{ kind: "meta", text: view.message }];
        case "ready":
            if (view.lines.length === 0) return [{ kind: "meta", text: "No lines here." }];
            if (view.added === 0 && view.removed === 0)
                return [...view.lines, { kind: "meta", text: "Nothing changed in these lines." }];
            return view.lines;
    }
}

const FENCE_PATTERN = new RegExp(
    `^\`\`\`${HAPPY_UI_FENCE_LABEL}[^\\n]*\\n([\\s\\S]*?)^\`\`\``,
    "gmu",
);

/** Every closed Happy UI fence in a message body, in order. */
export function happyUiFences(text: string): readonly string[] {
    if (!text.includes(`\`\`\`${HAPPY_UI_FENCE_LABEL}`)) return [];
    const out: string[] = [];
    for (const match of text.matchAll(FENCE_PATTERN)) out.push(match[1]!.replace(/\n$/u, ""));
    return out;
}

/**
 * What the grounding currently answers for every place a body's blocks name,
 * so a row is re-sized when a change finishes loading or the checkout moves.
 * Empty for a body with no block in it.
 */
export function happyUiSignature(text: string, grounding: HappyUiGrounding | undefined): string {
    const fences = happyUiFences(text);
    if (fences.length === 0) return "";
    const parts: string[] = [];
    for (const fence of fences) {
        const parsed = happyUiParse(fence);
        if (parsed.type !== "ready") continue;
        for (const reference of happyUiReferences(parsed.document)) {
            if (grounding === undefined) {
                parts.push("unknown");
                continue;
            }
            if (reference.lines === undefined) {
                parts.push(grounding.file(reference.path));
                continue;
            }
            const view = grounding.diff(reference.path, reference.lines);
            parts.push(
                view.type === "ready"
                    ? `ready:${String(view.lines.length)}:${String(view.added)}:${String(view.removed)}`
                    : view.type,
            );
        }
    }
    return parts.join("\u0000");
}

