import { happyUiParse, type HappyUiLineRange, type HappyUiNode } from "./happyUi";
import { happyUiDiffDisplayLines, type HappyUiGrounding } from "./happyUiGrounding";

/**
 * Painted height of a Happy UI block, resolved before it mounts.
 *
 * Every constant mirrors `styles/happy-ui.css` and `styles/diff-snippet.css`.
 * They are duplicated deliberately: reading them from the cascade needs a
 * mounted element, which is the thing the row model exists to avoid. Change
 * one and change the other.
 */
const BORDER = 2;
const PADDING = 16;
const NODE_GAP = 16;
const BODY_SIZE = 16;
const BODY_LINE = 24;
const STEP_GAP = 4;
const STEP_INDENT = 24;
const SIDE_GAP = 12;
const SIDE_PADDING = 12;
const SIDE_LABEL = 16;
const SIDE_LABEL_GAP = 4;
const SIDE_SIZE = 14;
const SIDE_LINE = 20;
const CHAPTER_GAP = 8;
const FILE_ROW = 24;
/** `.happy-diff-snippet`: header, code padding, line, border. */
const DIFF_HEADER = 28;
const DIFF_PADDING = 8;
const DIFF_LINE = 20;
const DIFF_BORDER = 2;
const REASON_SIZE = 14;
const REASON_LINE = 20;
const CODE_PADDING = 16;
const CODE_LINE = 20;

/** Wrapped height of plain UI-font text at one size and weight. */
export type HappyUiTextMeasure = (
    text: string,
    size: number,
    weight: number,
    lineHeight: number,
    measure: number,
) => number;

export interface HappyUiLayoutInput {
    readonly text: HappyUiTextMeasure;
    /** Height of one Mermaid fence at a measure, diagram or source. */
    readonly mermaid: (source: string, measure: number) => number;
    readonly grounding?: HappyUiGrounding;
}

function diffHeight(path: string, lines: HappyUiLineRange, input: HappyUiLayoutInput): number {
    const view = input.grounding?.diff(path, lines);
    const count = happyUiDiffDisplayLines(view).length;
    return DIFF_BORDER + DIFF_HEADER + DIFF_PADDING * 2 + count * DIFF_LINE;
}

function nodeHeight(node: HappyUiNode, measure: number, input: HappyUiLayoutInput): number {
    switch (node.type) {
        case "context":
            return input.text(node.text, BODY_SIZE, 500, BODY_LINE, measure);
        case "steps": {
            let total = 0;
            for (const [index, item] of node.items.entries()) {
                if (index > 0) total += STEP_GAP;
                total += input.text(item, BODY_SIZE, 400, BODY_LINE, measure - STEP_INDENT);
            }
            return total;
        }
        case "beforeAfter": {
            const side = Math.max(0, (measure - SIDE_GAP) / 2 - SIDE_PADDING * 2);
            const height = (text: string) =>
                SIDE_PADDING * 2 +
                SIDE_LABEL +
                SIDE_LABEL_GAP +
                input.text(text, SIDE_SIZE, 400, SIDE_LINE, side);
            return Math.max(height(node.before), height(node.after));
        }
        case "chapter": {
            let total = input.text(node.title, BODY_SIZE, 600, BODY_LINE, measure);
            if (node.text !== undefined)
                total += CHAPTER_GAP + input.text(node.text, BODY_SIZE, 400, BODY_LINE, measure);
            if (node.files.length > 0) total += CHAPTER_GAP + node.files.length * FILE_ROW;
            for (const child of node.children ?? [])
                total += CHAPTER_GAP + nodeHeight(child, measure, input);
            return total;
        }
        case "diff":
            return diffHeight(node.path, node.lines, input);
        case "mermaid":
            return input.mermaid(node.source, measure);
    }
}

/**
 * Height of one closed ` ```happy-ui ` fence wrapped at `measure` px, drawn
 * as a block. The streaming/source form is sized by the caller as ordinary
 * fenced code, which is what it is drawn as.
 */
export function happyUiBlockHeight(
    source: string,
    measure: number,
    input: HappyUiLayoutInput,
): number {
    const inner = Math.max(0, measure - BORDER - PADDING * 2);
    const parsed = happyUiParse(source);
    if (parsed.type === "invalid") {
        const lines = Math.max(1, source.split("\n").length);
        return (
            BORDER +
            PADDING * 2 +
            input.text(
                `This block could not be drawn: ${parsed.reason}`,
                REASON_SIZE,
                400,
                REASON_LINE,
                inner,
            ) +
            CHAPTER_GAP +
            CODE_PADDING * 2 +
            lines * CODE_LINE
        );
    }
    let total = 0;
    for (const [index, node] of parsed.document.children.entries()) {
        if (index > 0) total += NODE_GAP;
        total += nodeHeight(node, inner, input);
    }
    return BORDER + PADDING * 2 + total;
}

