import { type CSSProperties } from "react";
import { partitionComponentProps } from "./componentProps";
import { DiffSnippet } from "./DiffSnippet";
import { type FileOpenHandler } from "./fileReference";
import {
    happyUiParse,
    type HappyUiBeforeAfterNode,
    type HappyUiChapterNode,
    type HappyUiContextNode,
    type HappyUiDiffNode,
    type HappyUiDocument,
    type HappyUiFile,
    type HappyUiKind,
    type HappyUiMermaidNode,
    type HappyUiNode,
    type HappyUiStepsNode,
} from "./happyUi";
import { happyUiDiffDisplayLines, type HappyUiGrounding } from "./happyUiGrounding";
import { MermaidDiagram } from "./MermaidDiagram";
import { ScrollArea } from "./Scrollbar";

export type HappyUiBlockProps = {
    className?: string;
    "data-testid"?: string;
    /** The real change behind the block; absent, nothing is claimed about files. */
    grounding?: HappyUiGrounding;
    /** Opens a file a chapter or diff names, at the lines it named. */
    onFileOpen?: FileOpenHandler;
    /** The fence's text: a JSON tree in the Happy UI format. */
    source: string;
    style?: CSSProperties;
    variant?: "document" | "message";
};

function lineRangeLabel(file: Pick<HappyUiFile, "lines">): string | undefined {
    if (file.lines === undefined) return undefined;
    return file.lines.startLine === file.lines.endLine
        ? `:${String(file.lines.startLine)}`
        : `:${String(file.lines.startLine)}-${String(file.lines.endLine)}`;
}

function pathSplit(path: string): { readonly dir: string; readonly name: string } {
    const slash = path.lastIndexOf("/");
    return slash === -1
        ? { dir: "", name: path }
        : { dir: path.slice(0, slash + 1), name: path.slice(slash + 1) };
}

const ContextNode = ({ node }: { node: HappyUiContextNode }) => (
