        </div>
    </div>
);

const FileRow = ({
    file,
    kind,
    grounding,
    onFileOpen,
}: {
    file: HappyUiFile;
    kind: HappyUiKind;
    grounding: HappyUiGrounding | undefined;
    onFileOpen: FileOpenHandler | undefined;
}) => {
    const { dir, name } = pathSplit(file.path);
    const lines = lineRangeLabel(file);
