        ) : null}
        {(node.children ?? []).map((child, index) =>
            child.type === "diff" ? (
                <DiffNode
                    grounding={grounding}
                    key={`diff:${child.path}:${String(child.lines.startLine)}:${String(index)}`}
                    node={child}
                    onFileOpen={onFileOpen}
                />
            ) : (
                <MermaidNode key={`mermaid:${String(index)}`} node={child} />
            ),
        )}
    </section>
);

const Node = ({
    node,
    kind,
    grounding,
    onFileOpen,
}: {
    node: HappyUiNode;
    kind: HappyUiKind;
    grounding: HappyUiGrounding | undefined;
    onFileOpen: FileOpenHandler | undefined;
}) => {
    switch (node.type) {
        case "context":
            return <ContextNode node={node} />;
        case "steps":
            return <StepsNode node={node} />;
        case "beforeAfter":
            return <BeforeAfterNode node={node} />;
        case "chapter":
            return (
                <ChapterNode
                    grounding={grounding}
                    kind={kind}
                    node={node}
                    onFileOpen={onFileOpen}
                />
            );
        case "diff":
            return <DiffNode grounding={grounding} node={node} onFileOpen={onFileOpen} />;
        case "mermaid":
            return <MermaidNode node={node} />;
    }
};

function nodeKey(node: HappyUiNode, index: number): string {
    switch (node.type) {
        case "chapter":
            return `chapter:${node.title}:${String(index)}`;
        case "diff":
            return `diff:${node.path}:${String(node.lines.startLine)}:${String(index)}`;
        default:
            return `${node.type}:${String(index)}`;
    }
}

/**
 * An agent-authored component tree, drawn with Happy's own catalog.
 *
 * The source is a closed ` ```happy-ui ` fence holding the Happy UI JSON tree.
 * Nothing in it is interpreted as markup: text is text, a diff node shows
 * lines the grounding read from the real change, and a diagram goes through
 * the same Mermaid component the transcript already uses. A tree that cannot
 * be read stays on screen as its source, with the reason above it.
 */
export function HappyUiBlock(props: HappyUiBlockProps) {
    const [local] = partitionComponentProps(props, [
        "className",
        "data-testid",
        "grounding",
        "onFileOpen",
        "source",
        "style",
        "variant",
    ]);
    const variant = local.variant ?? "document";
    const parsed = happyUiParse(local.source);
    const className = (state: "ready" | "invalid") =>
        [
            "happy-ui-block",
            `happy-ui-block--${variant}`,
            state === "invalid" ? "happy-ui-block--invalid" : undefined,
            local.className,
        ]
            .filter(Boolean)
            .join(" ");
