        return (
            <div
                className={className("invalid")}
                data-happy-desktop-ui="happy-ui-block"
                data-render-state="invalid"
                data-testid={local["data-testid"]}
                style={local.style}
            >
                <p className="happy-ui-block__reason" data-happy-desktop-ui="happy-ui-reason">
                    This block could not be drawn: {parsed.reason}
                </p>
                <ScrollArea
                    axes="horizontal"
                    className="happy-ui-block__source"
                    viewportClassName="happy-ui-block__source-viewport"
                >
                    <pre>
                        <code>{local.source}</code>
                    </pre>
                </ScrollArea>
            </div>
        );
    const document: HappyUiDocument = parsed.document;
    return (
        <div
            className={className("ready")}
            data-happy-desktop-ui="happy-ui-block"
            data-kind={document.kind}
            data-render-state="ready"
            data-testid={local["data-testid"]}
            style={local.style}
        >
            {document.children.map((node, index) => (
                <Node
                    grounding={local.grounding}
                    key={nodeKey(node, index)}
                    kind={document.kind}
                    node={node}
                    onFileOpen={local.onFileOpen}
                />
            ))}
        </div>
    );
}

