    children: readonly MarkdownPhrasing[],
    style: MarkdownInlineStyle,
    lineHeight: number,
    measure: number,
    cache: MessageTextLayoutCache,
    footnotes: MarkdownFootnotes,
    trailingExtraWidth = 0,
    task = false,
    suffixText = "",
