    if (
        node.type === "text" ||
        node.type === "inlineCode" ||
        node.type === "break" ||
        node.type === "image" ||
        node.type === "imageReference" ||
        node.type === "html"
    )
        return;
    for (const child of node.children) markdownFootnoteReferenceCollect(child, footnotes);
