import type { Loadable } from "../conversation/loadable.js";
import { UserError } from "../types.js";
import type { HappyAgentChangedFileDocument, HappyAgentGitChangedFile } from "./happyAgentTypes.js";

/**
 * One changed file's two sides, as last read for the revision the Git
 * snapshot reported. `missing` is a file the current change does not touch:
 * that is an answer, not an absence, because a tour that names it is wrong.
 */
export type HappyAgentChangedFileDiff =
    | { readonly type: "loading" }
    | { readonly type: "missing" }
    | { readonly type: "error"; readonly error: UserError }
    | {
          readonly type: "ready";
          readonly document: HappyAgentChangedFileDocument;
          /** The working-tree identity this was read at; a newer one re-reads. */
          readonly revision: string;
      };

/** Every changed file asked for so far in one checkout, by workspace path. */
export type HappyAgentChangedFileDiffsSnapshot = ReadonlyMap<string, HappyAgentChangedFileDiff>;

/**
 * The changes behind the Happy UI blocks a conversation draws.
 *
 * A tour names files and line ranges; what it shows at them must be the real
 * diff. This store reads each named file's old and new sides once per
 * revision and keeps the answer, so a transcript can ask while it renders and
 * while it sizes rows. `request` only records what is wanted and starts a
 * read; it never publishes in its own call. A file the change does not
 * include is answered `missing` on the next tick.
 */
export interface HappyAgentChangedFileDiffsStore {
    get(): HappyAgentChangedFileDiffsSnapshot;
    subscribe(listener: () => void): () => void;
    /** Owner input: a file a visible block names. Safe to call every render. */
    request(path: string): void;
    [Symbol.dispose](): void;
}

export interface HappyAgentChangedFileDiffsDeps {
    /** The live Git change for a path in this checkout, or nothing if unchanged. */
    readonly changeFind: (path: string) => HappyAgentGitChangedFile | undefined;
    /** Reads both sides of one changed file. */
    readonly read: (
        path: string,
        change: HappyAgentGitChangedFile,
        signal: AbortSignal,
    ) => Promise<HappyAgentChangedFileDocument>;
}

const EMPTY: HappyAgentChangedFileDiffsSnapshot = new Map();

function userError(error: unknown): UserError {
    if (error instanceof UserError) return error;
    return new UserError(
        error instanceof Error && error.message ? error.message : "The change could not be read.",
        undefined,
        error,
    );
}

export function happyAgentChangedFileDiffsStoreCreate(
    deps: HappyAgentChangedFileDiffsDeps,
): HappyAgentChangedFileDiffsStore {
    const listeners = new Set<() => void>();
    let snapshot = EMPTY;
    /** Reads in flight, by path, with the revision each is reading. */
    const reading = new Map<
        string,
        { readonly revision: string; readonly abort: AbortController }
    >();
    /** Answers decided inside `request`, published on the next tick. */
    let pending: Map<string, HappyAgentChangedFileDiff> | undefined;
    let disposed = false;

    const publish = (entries: ReadonlyMap<string, HappyAgentChangedFileDiff>): void => {
        if (disposed) return;
        const next = new Map(snapshot);
        for (const [path, diff] of entries) next.set(path, diff);
        snapshot = next;
        for (const listener of listeners) listener();
    };
    const later = (path: string, diff: HappyAgentChangedFileDiff): void => {
        if (pending === undefined) {
            pending = new Map();
            queueMicrotask(() => {
                const batch = pending;
                pending = undefined;
                if (batch !== undefined) publish(batch);
            });
        }
        pending.set(path, diff);
    };
    const read = (path: string, change: HappyAgentGitChangedFile): void => {
        const abort = new AbortController();
        reading.set(path, { revision: change.revision, abort });
        void deps
            .read(path, change, abort.signal)
            .then(
                (document): HappyAgentChangedFileDiff => ({
                    type: "ready",
                    document,
                    revision: change.revision,
                }),
                (error: unknown): HappyAgentChangedFileDiff => ({
                    type: "error",
                    error: userError(error),
                }),
            )
            .then((diff) => {
                if (abort.signal.aborted || reading.get(path)?.abort !== abort) return;
                reading.delete(path);
                publish(new Map([[path, diff]]));
            });
    };

    return {
        get: () => snapshot,
        subscribe(listener) {
            listeners.add(listener);
            return () => {
                listeners.delete(listener);
            };
        },
        request(path) {
            if (disposed) return;
            const change = deps.changeFind(path);
            const held = pending?.get(path) ?? snapshot.get(path);
            if (change === undefined) {
                // Not in the change any more: whatever was read is stale, and
                // an answer in flight is for a revision that no longer exists.
                reading.get(path)?.abort.abort();
                reading.delete(path);
                if (held?.type !== "missing") later(path, { type: "missing" });
                return;
            }
            if (held?.type === "ready" && held.revision === change.revision) return;
            const inFlight = reading.get(path);
            if (inFlight?.revision === change.revision) return;
            inFlight?.abort.abort();
            if (held?.type !== "loading") later(path, { type: "loading" });
            read(path, change);
        },
        [Symbol.dispose]() {
            if (disposed) return;
            disposed = true;
            for (const entry of reading.values()) entry.abort.abort();
            reading.clear();
            pending = undefined;
            listeners.clear();
        },
    };
}

/** The store a surface with no checkout behind it uses: everything is unknown. */
export const happyAgentChangedFileDiffsStoreNoop: HappyAgentChangedFileDiffsStore = {
    get: () => EMPTY,
    subscribe: () => () => undefined,
    request: () => undefined,
    [Symbol.dispose]: () => undefined,
};

export type { Loadable as HappyAgentChangedFileDiffsLoadable };

