import type {
    HappyAgentChangedFileDiffsSnapshot,
    HappyAgentChangedFileDiffsStore,
} from "happy-desktop-state";
import {
    happyUiDiffLines,
    type HappyUiDiffView,
    type HappyUiFileView,
    type HappyUiGrounding,
    type HappyUiLineRange,
} from "happy-desktop-ui";

/**
 * The real change behind the Happy UI blocks one conversation draws, read
 * from the checkout's changed-file store.
 *
 * Built from an immutable snapshot, so a new snapshot is a new value and the
 * transcript re-renders and re-sizes the rows whose blocks name what changed.
 * Asking for a file that has not been read yet records the want; the store
 * answers later through its subscription, never inside this call.
 */
export function happyUiGroundingCreate(input: {
    readonly diffs: HappyAgentChangedFileDiffsSnapshot;
    readonly store: HappyAgentChangedFileDiffsStore;
}): HappyUiGrounding {
    /** One range's lines, computed once per snapshot rather than per render. */
    const lines = new Map<string, HappyUiDiffView>();
    return {
        diff(path: string, range: HappyUiLineRange): HappyUiDiffView {
            input.store.request(path);
            const held = input.diffs.get(path);
            if (held === undefined || held.type === "loading") return { type: "loading" };
            if (held.type === "missing") return { type: "missing" };
            if (held.type === "error") return { type: "error", message: held.error.message };
            const key = `${path}\u0000${String(range.startLine)}\u0000${String(range.endLine)}\u0000${held.revision}`;
            const cached = lines.get(key);
            if (cached !== undefined) return cached;
            const view = happyUiDiffLines(
                {
                    path,
                    oldContent: held.document.oldContent,
                    newContent: held.document.newContent,
                },
                range,
            );
            lines.set(key, view);
            return view;
        },
        file(path: string): HappyUiFileView {
            input.store.request(path);
            const held = input.diffs.get(path);
            if (held === undefined || held.type === "loading") return "unknown";
            return held.type === "missing" ? "unchanged" : "changed";
        },
    };
}
